CREATE DATABASE IF NOT EXISTS codequest_db;
USE codequest_db;
CREATE TABLE IF NOT EXISTS users(id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) UNIQUE NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, xp INT DEFAULT 0, level INT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins(id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS missions(id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(100) NOT NULL, question TEXT NOT NULL, option1 VARCHAR(255) NOT NULL, option2 VARCHAR(255) NOT NULL, option3 VARCHAR(255) NOT NULL, option4 VARCHAR(255) NOT NULL, correct_answer INT NOT NULL, xp_reward INT DEFAULT 10, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mission_submissions(id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, mission_id INT NOT NULL, selected_answer INT NOT NULL, is_correct BOOLEAN NOT NULL, xp_earned INT DEFAULT 0, submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY one_attempt_per_mission(user_id,mission_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(mission_id) REFERENCES missions(id));
